#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-04
# Overhead per tracing tier from a scripts/campaign_tiers.sh campaign: for each tier a combined directory
# (baseline_<i> + the tier's nsys_<i>, symlinks) is fed to scripts/autoware_runs/analyze_overhead_modes.py.
# Usage: scripts/tiers_overhead.sh ~/fish_traces/campaign_tiers_<stamp>
set -u
C=${1:?campaign_tiers dir}; cd "$(dirname "$0")/.."
BASE=$(grep -h "campaign →" "$C/baseline.log" | head -1 | sed 's/.*→ //' | cut -d' ' -f1)
for T in min default max; do
  [ -f "$C/tier_$T.log" ] || continue
  D=$(grep -h "campaign →" "$C/tier_$T.log" | head -1 | sed 's/.*→ //' | cut -d' ' -f1)
  R="$C/combined_$T"; rm -rf "$R"; mkdir -p "$R"
  for d in "$BASE"/baseline_*; do ln -s "$d" "$R/$(basename "$d")"; done
  for d in "$D"/nsys_*; do ln -s "$d" "$R/$(basename "$d")"; done
  echo "=================== tier $T  (baseline $BASE, traced $D)"
  python3 scripts/autoware_runs/analyze_overhead_modes.py "$R" 2>&1 | grep -v "^$" | head -40
done
